const ELEMENT_PROP_KEYS = new Set(["theme","minutes","fontWeight","stagger","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  minutes: 4,
  fontWeight: 500,
  stagger: 2.5,
  accent: "#3B5BFD",
  fontFamily: "Instrument Sans",
